python3 << 'EOF'
import json
import re

with open('/root/DATA/products/PersonalizeForce.json', 'r') as f:
    data = json.load(f)

slack_messages = data.get('slack', [])

# Find demo URLs
demo_urls = []

for msg in slack_messages:
    text = msg.get('Message', {}).get('User', {}).get('text', '')

    # Look for demo URLs
    if 'demo' in text.lower():
        # Extract URLs
        urls = re.findall(r'https?://[^\s<>"]+', text)
        for url in urls:
            if 'demo' in url.lower():
                demo_urls.append(url)

    # Also check thread replies
    for reply in msg.get('ThreadReplies', []):
        reply_text = reply.get('User', {}).get('text', '')
        if 'demo' in reply_text.lower():
            urls = re.findall(r'https?://[^\s<>"]+', reply_text)
            for url in urls:
                if 'demo' in url.lower():
                    demo_urls.append(url)

print("Demo URLs found:")
for url in demo_urls:
    print(f"  {url}")

print(f"\nUnique demo URLs: {list(set(demo_urls))}")
EOF

